class InvalidCellType(Exception):
    """
    Raised when given cell_type is different from "nr", "lte", "gsm", "wcdma"
    """
    pass


class CellIdNotFound(Exception):
    """Raised when cell ID parameter is not found for given cell"""
    pass


class ParameterNotFound(Exception):
    """ Raised when desired parameter could not be found"""
    pass


class CellIsNotSuperCell(Exception):
    """ Raised when trying to check supercell parameters for a regular cell """
    pass


class InvalidRan(Exception):
    """
    Raised when RAN is neither classical nor cloud
    """
    pass
